-- READ ONLY: use the Supabase audit connector; never ship privileged access to the renderer.
SELECT jsonb_build_object('patches',(SELECT jsonb_agg(to_jsonb(p)) FROM patches p WHERE is_current),'totals',jsonb_build_object('moves',(SELECT count(*) FROM moves),'commands',(SELECT count(*) FROM move_commands),'frames',(SELECT count(*) FROM move_frame_data)),'characters',(SELECT jsonb_agg(jsonb_build_object('id',c.id,'slug',c.slug,'moves',(SELECT jsonb_agg(jsonb_build_object('id',m.id,'slug',m.slug,'name',m.name_ja,'moveType',m.move_type,'strengthVariant',m.strength_variant,'status',m.status,'displayOrder',m.display_order,'commands',(SELECT jsonb_agg(to_jsonb(mc) ORDER BY mc.sort_order) FROM move_commands mc WHERE mc.move_id=m.id),'frames',(SELECT jsonb_agg(to_jsonb(f)) FROM move_frame_data f WHERE f.move_id=m.id),'moveOfficialEvidence',EXISTS(SELECT 1 FROM entity_sources es JOIN sources s ON s.id=es.source_id WHERE es.entity_type='move' AND es.entity_id=m.id AND s.reliability_level='official'),'classicCommandOfficialEvidence',EXISTS(SELECT 1 FROM move_commands mc JOIN entity_sources es ON es.entity_type='move_command' AND es.entity_id=mc.id JOIN sources s ON s.id=es.source_id WHERE mc.move_id=m.id AND mc.control_scheme='classic' AND s.reliability_level='official'),'frameOfficialEvidence',EXISTS(SELECT 1 FROM move_frame_data f JOIN entity_sources es ON es.entity_id=f.id AND es.entity_type IN ('frame','move_frame_data') JOIN sources s ON s.id=es.source_id WHERE f.move_id=m.id AND f.valid_to_patch_id IS NULL AND s.reliability_level='official')) ORDER BY m.display_order,m.slug) FROM moves m WHERE m.character_id=c.id AND m.status<>'archived' AND m.move_type IN ('normal','unique','target_combo','special','throw','super'))) ORDER BY c.slug) FROM characters c WHERE c.status='published')) AS export;
